components.css:
.ds-btn-primary { display: inline-block; border: 0; border-radius: 6px; cursor: pointer; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; padding: 7px 10px; background: var(--primary-bg, #1f6feb); color: var(--primary-fg, #fff); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--primary-bg, #1f6feb); outline-offset: 1px; }
.ds-btn-primary:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-btn-secondary { display: inline-block; border: 0; border-radius: 6px; cursor: pointer; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; padding: 7px 10px; background: var(--secondary-bg, #e9edf3); color: var(--secondary-fg, #26344c); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--primary-bg, #1f6feb); outline-offset: 1px; }
.ds-btn-secondary:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-btn-danger { display: inline-block; border: 1px solid var(--danger, #c2261f); border-radius: 6px; cursor: pointer; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; padding: 7px 10px; background: transparent; color: var(--danger, #c2261f); }
.ds-btn-danger:hover { background: var(--danger-bg, rgba(194, 38, 31, 0.08)); }
.ds-btn-danger:focus-visible { outline: 2px solid var(--primary-bg, #1f6feb); outline-offset: 1px; }

.ds-icon-btn { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 6px; cursor: pointer; background: var(--secondary-bg, #e9edf3); color: var(--secondary-fg, #26344c); }
.ds-icon-btn:hover { filter: brightness(0.95); }
.ds-icon-btn:focus-visible { outline: 2px solid var(--primary-bg, #1f6feb); outline-offset: 1px; }

.ds-card { background: var(--card-bg, #fff); border: 1px solid var(--card-border, #dfe4ec); border-radius: 8px; padding: 12px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.ds-card-title { margin: 0; font-size: 14px; font-weight: 700; line-height: 1.3; color: var(--fg, #172033); }
.ds-card-copy { margin: 4px 0 0; font-size: 12px; color: var(--muted, #687286); }

.ds-job { display: grid; gap: 4px; padding: 8px; border-radius: 6px; background: var(--job-bg, #f7f9fc); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; color: var(--fg, #172033); }
.ds-job-title { font-weight: 600; overflow-wrap: anywhere; }
.ds-job-meta { color: var(--muted, #687286); font-size: 11px; overflow-wrap: anywhere; }
.ds-job-actions { display: flex; gap: 6px; margin-top: 4px; }
.ds-job-btn { border: 0; border-radius: 6px; cursor: pointer; font: inherit; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 11px; padding: 5px 8px; background: var(--secondary-bg, #e9edf3); color: var(--secondary-fg, #26344c); }
.ds-job-btn:focus-visible { outline: 2px solid var(--primary-bg, #1f6feb); outline-offset: 1px; }

.ds-field { display: grid; gap: 4px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; color: var(--muted, #687286); }
.ds-input { border: 1px solid var(--card-border, #dfe4ec); border-radius: 6px; background: var(--job-bg, #f7f9fc); color: var(--fg, #172033); font: inherit; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 13px; padding: 7px 8px; }
.ds-input:focus-visible { outline: 2px solid var(--primary-bg, #1f6feb); outline-offset: 1px; }
.ds-input[aria-invalid="true"] { border-color: var(--danger, #c2261f); outline-color: var(--danger, #c2261f); }

.ds-notice { min-height: 16px; margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; color: var(--notice, #6b4b00); }
.ds-notice-info { color: var(--muted, #687286); }
.ds-notice-warn { color: var(--notice, #6b4b00); }
.ds-notice-success { color: var(--success, #186b31); font-weight: 600; }
.ds-notice-error { color: var(--danger, #c2261f); }
